
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import Slider from "react-slick";

import Footer from './Footer';
import Profile_pic from './images/Profile_pic.jpg';
import research from './images/research.jpeg';
import nhc from './images/nhc.png';
import enantio from './images/enantio.png';
import bcb from './images/bcb.png';
import c5 from './images/c5.png';
import experience_img from './images/experience-img.jpg';
import quote from './images/quote.png';
import Header from './Header';
import { NavLink } from 'react-router-dom';

const Home = () => {
    const settings = {
        dots: true,
        infinite: true,
        autoplay: true,
        autoplaySpeed: 3500,
        arrows: true,
        speed: 600,
        slidesToShow: 1,
        slidesToScroll: 1
    };


    return (
        <div>
            <div className="hero_area">
                {/* header section strats */}
                <Header words="Priyanshu" />
                {/* end header section */}
                {/* slider section */}
                <section className="slider_section ">

                    <div className="carousel-inner">
                        <div className="carousel-item active">
                            <div className="container-fluid">
                                <div className="row">
                                    <div className="col-md-5 offset-md-1">
                                        <div className="detail-box">
                                            <h1>
                                                Hi,<br /> this is Priyanshu Gupta’s website.
                                            </h1>
                                            <p>
                                                His current research mainly revolves around utilization of
                                                Non-covalent interactions in organic synthesis and
                                                utilization of computational methods to understand organic
                                                reactions.
                                                <br />
                                            </p>
                                            <div className="btn-box">
                                                <NavLink to="/about" className="btn-1">
                                                    About Me
                                                </NavLink>
                                            </div>
                                        </div>
                                    </div>
                                    <div className="offset-md-1 col-md-4 img-container">
                                        <div className="img-box">
                                            <img src={Profile_pic} alt="profile pic" />
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </section>
                {/* end slider section */}
            </div>
            <section className="experience_section layout_padding">
                <div className="container">
                    <div className="row">
                        <div className="col-md-5">
                            <div className="img-box">
                                <img src={research} alt="experience" />
                            </div>
                        </div>
                        <div className="col-md-7">
                            <div className="detail-box">
                                <div className="heading_container">
                                    <h2>Research Interests</h2>
                                </div>
                                <p style={{ textAlign: "justify" }}>
                                    He started his research experience with reactions of
                                    N-heterocyclic carbenes (NHCs) including annulation reactions, and
                                    then enantioselective amidation reactions. For the BS project, he
                                    chose to expand the scope of nucleophiles to peroxides which could
                                    be intercepted by Bicyclo[1.1.0]butanes to access highly
                                    functionalized cyclobutanes. He is currently exploring other
                                    research areas within the realm of organic chemistry which gives
                                    the flavour of computational studies.

                                    (<i>The image on the left is an AI-generated image.</i>)
                                </p>
                                <div className="btn-box fat">
                                    <NavLink to="/publications" className="btn-1">
                                        Read More (Publications)
                                    </NavLink>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </section>
            <section className="category_section layout_padding">
                <div className="container">
                    <div className="heading_container">
                        <h2>Interests</h2>
                    </div>
                    <div className="category_container">
                        <div className="box">
                            <div className="img-box">
                                <img src={nhc} width="100px" alt="nhc" />
                            </div>
                            <div className="detail-box">
                                <h5>NHCs</h5>
                            </div>
                        </div>
                        <div className="box">
                            <div className="img-box">
                                <img src={enantio} alt="" />
                            </div>
                            <div className="detail-box">
                                <h5>Enantioselective reactions</h5>
                            </div>
                        </div>
                        <div className="box">
                            <div className="img-box">
                                <img src={bcb} alt="BCBs" />
                            </div>
                            <div className="detail-box">
                                <h5>BCBs</h5>
                            </div>
                        </div>
                    </div>
                </div>
            </section>
            <section className="freelance_section ">
                <div id="accordion">
                    <div className="container-fluid">
                        <div className="row">
                            <div className="col-md-5 offset-md-1">
                                <div className="detail-box">
                                    <div className="heading_container">
                                        <h2>Research Experience</h2>
                                    </div>
                                    <div className="tab_container">
                                        <div
                                            className="t-link-box"
                                            data-toggle="collapse"
                                            data-target="#collapseOne"
                                            aria-expanded="true"
                                            aria-controls="collapseOne"
                                        >
                                            <div className="img-box">
                                                <img src={c5} alt="" />
                                            </div>
                                            <div className="detail-box">
                                                <h5>BS project</h5>
                                                <h3>Utilizing BCBs to afford various carbacycles.</h3>
                                            </div>
                                        </div>
                                        <div
                                            className="t-link-box"
                                            data-toggle="collapse"
                                            data-target="#collapseOne"
                                            aria-expanded="true"
                                            aria-controls="collapseOne"
                                        >
                                            <div className="img-box">
                                                <img src={c5} alt="" />
                                            </div>
                                            <div className="detail-box">
                                                <h5>Research Stint</h5>
                                                <h3>
                                                    Preparing substrates for the photocatalytic reduction of
                                                    benzenes to cyclohexenes.
                                                </h3>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div className="col-md-6">
                                <div
                                    className="collapse show"
                                    id="collapseOne"
                                    aria-labelledby="headingOne"
                                    data-parent="#accordion"
                                >
                                    <div className="img-box" style={{ width: "80%" }}>
                                        <img src={experience_img} alt="" />
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            <section className="client_section layout_padding">
                <div className="container">
                    <div className="row">
                        <div className="col-lg-9 col-md-10 mx-auto">
                            <div className="heading_container">
                                <h2>Hobbies</h2>
                            </div>
                            <div
                                id="carouselExampleControls"
                                className="carousel slide"
                                data-ride="carousel"
                            >
                                <div className="carousel_inner">
                                    <Slider {...settings}>
                                        <div className="carousel-item slide">
                                            <div className="detail-box">
                                                <h4>Watching Shows</h4>
                                                <p>
                                                    Recently, I have discovered the dopamine release I obtain
                                                    after watching movies, animes, etc.
                                                </p>
                                                <img src={quote} alt="" />
                                            </div>
                                        </div>
                                        <div className="carousel-item slide">
                                            <div className="detail-box">
                                                <h4>Reading</h4>
                                                <p>
                                                    There are lots of things which could be read apart from the
                                                    objective of research, such as someone's mind?!
                                                </p>
                                                <img src={quote} alt="" />
                                            </div>
                                        </div>
                                        <div className="carousel-item slide">
                                            <div className="detail-box">
                                                <h4>Travelling</h4>
                                                <p>
                                                    There are unlimited number of places where I have never
                                                    been.
                                                </p>
                                                <img src={quote} alt="" />
                                            </div>
                                        </div>
                                    </Slider>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

            </section>


            <Footer />
        </div>

    )
}

export default Home;