import { NavLink } from "react-router-dom"
export default function Box (props) {
    return (
      <div className="box">
        
        <div className="detail-box">
          <h5>
            <NavLink to={props.url} target="_blank" style={{color:"whitesmoke"}}>
              {" "}
              {props.title}
            </NavLink>
          </h5>
        </div>
      </div>
    )
}