import Header from './Header';
import Footer from './Footer';
import { NavLink } from 'react-router-dom';
import Profile_pic from './images/Profile_pic.jpg';
import about_img from './images/about-img.jpg';
import f4 from './images/f4.png';

export default function About() {
    return (
        <div className='sub_page'>
            <div className='hero_area'>
                <Header words='About' />
            </div>
            <section className="experience_section layout_padding-top layout_padding2-bottom">
                <div className="container">
                    <div className="row">
                        <div className="col-md-5">
                            <div className="img-box">
                                <img src={Profile_pic} alt="profile_pic" />
                            </div>
                        </div>
                        <div className="col-md-7">
                            <div className="detail-box">
                                <div className="heading_container">
                                    <h2>Priyanshu Gupta</h2>
                                </div>
                                <p>
                                    He was born in Delhi, India. He completed his undergraduate studies in Chemistry at the Indian Institute of Science, Bengaluru, in July 2025. During his undergraduate program, he undertook a research stint in Prof. Weisenfeldt’s lab from May to July 2024. He completed his undergraduate project in Prof. Biju’s lab. He is currently a graduate student at the University of Florida.
                                </p>
                                <div className="btn-box">
                                    <NavLink to="/CV.pdf" target="_blank" rel='noopener noreferrer' className="btn-1">
                                        CV
                                    </NavLink>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </section>
            <section className="about_section layout_padding-bottom">
                <div className="container">
                    <div className="row">
                        <div className="col-md-10 col-lg-9 mx-auto">
                            <div className="img-box">
                                <img src={about_img} alt="" />
                            </div>
                        </div>
                    </div>
                    <div className="detail-box">
                        <h2>Achievements</h2>
                        <section className="freelance_section ">
                            <div id="accordion">
                                <div className="container-fluid">
                                    <div className="row">
                                        <div className="col-md-12 offset-md-1">
                                            <div className="detail-box">
                                                <div className="tab_container">
                                                    <div
                                                        className="t-link-box"
                                                        data-toggle="collapse"
                                                        data-target="#collapseOne"
                                                        aria-expanded="false"
                                                        aria-controls="collapseOne"
                                                    >
                                                        <div className="img-box">
                                                            <img src={f4} alt="" />
                                                        </div>
                                                        <div className="detail-box">
                                                            <h3>
                                                                Graduate Aptitude Test in Engineering (GATE) - 2024
                                                            </h3>
                                                            <h5>
                                                                Secured All India Rank (AIR) - 51 in{" "}
                                                                <b>Chemistry</b>
                                                            </h5>
                                                        </div>
                                                    </div>
                                                    <div
                                                        className="t-link-box collapsed"
                                                        data-toggle="collapse"
                                                        data-target="#collapseTwo"
                                                        aria-expanded="false"
                                                        aria-controls="collapseTwo"
                                                    >
                                                        <div className="img-box">
                                                            <img src={f4} alt="" />
                                                        </div>
                                                        <div className="detail-box">
                                                            <h3>Joint Entrance Exam (JEE) — Main | 2021</h3>
                                                            <h5>Obtained percentile: 99.1412010.</h5>
                                                        </div>
                                                    </div>
                                                    <div
                                                        className="t-link-box collapsed"
                                                        data-toggle="collapse"
                                                        data-target="#collapseThree"
                                                        aria-expanded="false"
                                                        aria-controls="collapseThree"
                                                    >
                                                        <div className="img-box">
                                                            <img src={f4} alt="" />
                                                        </div>
                                                        <div className="detail-box">
                                                            <h3>KVPY SA fellow | 2020</h3>
                                                            <h5>Achieved AIR 252.</h5>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </section>
                    </div>
                </div>
            </section>
            <Footer />
        </div>
    )
}   